import{_ as t,o as r,c as a,ae as o}from"./chunks/framework.Co1PSFSm.js";const f=JSON.parse('{"title":"","description":"Various projects can integrate into Fresh to easily add functionality to your\\nproject.\\n","frontmatter":{"description":"Various projects can integrate into Fresh to easily add functionality to your\\nproject.\\n"},"headers":[],"relativePath":"en/latest/1.x/integrations/index.md","filePath":"en/latest/1.x/integrations/index.md"}'),n={name:"en/latest/1.x/integrations/index.md"};function s(h,e,i,d,c,l){return r(),a("div",null,[...e[0]||(e[0]=[o('<p>This section of the docs showcases modules or other projects that integrate with Fresh. These integrations can be used to add functionality to your project.</p><h2 id="fresh-charts" tabindex="-1"><code>fresh_charts</code> <a class="header-anchor" href="#fresh-charts" aria-label="Permalink to &quot;`fresh_charts`&quot;">​</a></h2><p>Fresh charts allows for easy integration of <a href="https://www.chartjs.org/" title="Chart.js" target="_blank" rel="noreferrer">Chart.js</a> charts into your Fresh project. It provides a <code>Chart</code> JSX component that can be used to render charts on the server and client.</p><p>A live demo can be found here: <a href="https://fresh-charts.deno.dev/" target="_blank" rel="noreferrer">https://fresh-charts.deno.dev/</a></p><p>Documentation for the module can be found here: <a href="https://deno.land/x/fresh_charts" target="_blank" rel="noreferrer">https://deno.land/x/fresh_charts</a></p><h2 id="fresh-marionette" tabindex="-1"><code>fresh_marionette</code> <a class="header-anchor" href="#fresh-marionette" aria-label="Permalink to &quot;`fresh_marionette`&quot;">​</a></h2><p>Fresh Marionette allows you to start writing end 2 end browser tests in your Fresh projects with a single import. Then you can run those browser tests in a GitHub Actions workflow.</p><p>Documentation for the module can be found here: <a href="https://deno.land/x/fresh_marionette" target="_blank" rel="noreferrer">https://deno.land/x/fresh_marionette</a></p><p>An example project that runs the tests in a GitHub Actions workflow: <a href="https://marionette.deno.dev" target="_blank" rel="noreferrer">https://marionette.deno.dev</a></p><p>Fresh Marionette works with VSCode too! - <a href="https://youtu.be/OG77NdqL164" target="_blank" rel="noreferrer">https://youtu.be/OG77NdqL164</a></p>',10)])])}const u=t(n,[["render",s]]);export{f as __pageData,u as default};
